-- Runs after 0007_curated_dinner_library.sql.
-- A reviewed, attributed CC BY-SA 4.0 starter catalogue. This migration is
-- deliberately static: running it never fetches the web or changes household copies.

do $$
declare
  v_collection_id uuid;
  v_recipes jsonb := $recipes$[{"slug":"hamburger","title":"Classic Hamburgers","description":"Pan-seared beef patties in buns with simple toppings.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Hamburger","servings":4,"instructions":"Season and shape the beef into four patties. Sear in a hot pan until cooked through. Serve in buns with lettuce, tomato, and condiments.","ingredients":[{"itemName":"beef mince","quantity":500,"unit":"g","notes":null},{"itemName":"hamburger buns","quantity":4,"unit":"each","notes":null},{"itemName":"lettuce","quantity":4,"unit":"piece","notes":null},{"itemName":"tomato","quantity":1,"unit":"each","notes":null},{"itemName":"ketchup","quantity":4,"unit":"tbsp","notes":null}],"tags":["course-dinner","cuisine-american","protein-beef","method-stovetop","method-quick"]},{"slug":"basic-risotto","title":"Basic Risotto","description":"Creamy Italian-style rice finished with cheese.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Risotto%20(Basic)","servings":4,"instructions":"Soften onion in oil. Toast rice, then add hot stock a ladle at a time, stirring until absorbed. Finish with butter and Parmesan.","ingredients":[{"itemName":"arborio rice","quantity":300,"unit":"g","notes":null},{"itemName":"vegetable stock","quantity":1,"unit":"l","notes":null},{"itemName":"onion","quantity":1,"unit":"each","notes":null},{"itemName":"Parmesan","quantity":60,"unit":"g","notes":null},{"itemName":"butter","quantity":30,"unit":"g","notes":null}],"tags":["course-dinner","cuisine-italian","dietary-vegetarian","method-stovetop"]},{"slug":"egg-rolls","title":"Vegetable Egg Rolls","description":"Crisp rolls with cabbage and carrot filling.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Egg%20Roll","servings":4,"instructions":"Stir-fry cabbage, carrot, and garlic until just tender. Cool, wrap in egg-roll wrappers, then bake or fry until crisp. Serve with dipping sauce.","ingredients":[{"itemName":"egg roll wrappers","quantity":8,"unit":"each","notes":null},{"itemName":"cabbage","quantity":300,"unit":"g","notes":null},{"itemName":"carrot","quantity":2,"unit":"each","notes":null},{"itemName":"garlic","quantity":2,"unit":"clove","notes":null},{"itemName":"soy sauce","quantity":2,"unit":"tbsp","notes":null}],"tags":["course-dinner","cuisine-asian","dietary-vegetarian","method-oven"]},{"slug":"bean-burritos","title":"Black Bean Burritos","description":"Hearty tortilla wraps with beans, rice, and fresh toppings.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Burrito","servings":4,"instructions":"Warm beans with spices. Fill tortillas with rice, beans, cheese, and salsa; roll tightly and toast seam-side down in a pan.","ingredients":[{"itemName":"tortillas","quantity":4,"unit":"each","notes":null},{"itemName":"black beans","quantity":2,"unit":"can","notes":null},{"itemName":"cooked rice","quantity":2,"unit":"cup","notes":null},{"itemName":"cheddar","quantity":120,"unit":"g","notes":null},{"itemName":"salsa","quantity":1,"unit":"cup","notes":null}],"tags":["course-dinner","cuisine-mexican","dietary-vegetarian","method-stovetop","method-quick"]},{"slug":"paella-valenciana","title":"Paella Valenciana","description":"Spanish rice with chicken, vegetables, and saffron-style seasoning.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Paella%20Valenciana","servings":4,"instructions":"Brown chicken and vegetables in a wide pan. Stir in rice, tomato, stock, and saffron, then simmer uncovered until the rice is tender.","ingredients":[{"itemName":"chicken thighs","quantity":600,"unit":"g","notes":null},{"itemName":"short grain rice","quantity":300,"unit":"g","notes":null},{"itemName":"chicken stock","quantity":750,"unit":"ml","notes":null},{"itemName":"tomato","quantity":2,"unit":"each","notes":null},{"itemName":"green beans","quantity":200,"unit":"g","notes":null}],"tags":["course-dinner","cuisine-spanish","protein-chicken","method-one-pot","method-stovetop"]},{"slug":"beef-tacos","title":"Beef Tacos","description":"Seasoned beef in crisp or soft taco shells.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Tacos","servings":4,"instructions":"Brown beef with onion and taco seasoning. Warm shells, then fill with beef, lettuce, tomato, cheese, and salsa.","ingredients":[{"itemName":"beef mince","quantity":500,"unit":"g","notes":null},{"itemName":"taco shells","quantity":8,"unit":"each","notes":null},{"itemName":"onion","quantity":1,"unit":"each","notes":null},{"itemName":"lettuce","quantity":1,"unit":"bunch","notes":null},{"itemName":"cheddar","quantity":100,"unit":"g","notes":null}],"tags":["course-dinner","cuisine-mexican","protein-beef","method-stovetop","method-quick"]},{"slug":"spaghetti-carbonara","title":"Spaghetti Carbonara","description":"Silky pasta with egg, cheese, and crisp pork.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Spaghetti%20alla%20Carbonara","servings":4,"instructions":"Cook spaghetti. Fry pancetta until crisp. Toss hot pasta off the heat with beaten eggs, Parmesan, pepper, and a splash of pasta water.","ingredients":[{"itemName":"spaghetti","quantity":400,"unit":"g","notes":null},{"itemName":"pancetta","quantity":150,"unit":"g","notes":null},{"itemName":"eggs","quantity":3,"unit":"each","notes":null},{"itemName":"Parmesan","quantity":80,"unit":"g","notes":null},{"itemName":"black pepper","quantity":1,"unit":"tsp","notes":null}],"tags":["course-dinner","cuisine-italian","protein-pork","method-stovetop","method-quick"]},{"slug":"vegetable-fried-rice","title":"Vegetable Fried Rice","description":"Fast skillet rice with egg and vegetables.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Fried%20Rice","servings":4,"instructions":"Scramble egg in a wok. Add vegetables and cold rice, then stir-fry with soy sauce and sesame oil until hot and lightly crisp.","ingredients":[{"itemName":"cooked rice","quantity":4,"unit":"cup","notes":null},{"itemName":"eggs","quantity":3,"unit":"each","notes":null},{"itemName":"frozen mixed vegetables","quantity":300,"unit":"g","notes":null},{"itemName":"soy sauce","quantity":3,"unit":"tbsp","notes":null},{"itemName":"sesame oil","quantity":1,"unit":"tbsp","notes":null}],"tags":["course-dinner","cuisine-asian","dietary-vegetarian","method-stovetop","method-quick"]},{"slug":"jambalaya","title":"Chicken and Sausage Jambalaya","description":"Cajun-style rice with chicken, sausage, and vegetables.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Jambalaya%20I","servings":4,"instructions":"Brown chicken and sausage. Cook onion, celery, and capsicum, then add rice, tomatoes, stock, and seasoning. Simmer until tender.","ingredients":[{"itemName":"chicken thighs","quantity":400,"unit":"g","notes":null},{"itemName":"smoked sausage","quantity":250,"unit":"g","notes":null},{"itemName":"rice","quantity":300,"unit":"g","notes":null},{"itemName":"diced tomatoes","quantity":1,"unit":"can","notes":null},{"itemName":"chicken stock","quantity":750,"unit":"ml","notes":null}],"tags":["course-dinner","cuisine-cajun","protein-chicken","protein-pork","method-one-pot"]},{"slug":"arroz-con-pollo","title":"Arroz con Pollo","description":"One-pot chicken and rice with tomato and peas.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Arroz%20con%20Pollo%20(Rice%20and%20Chicken)","servings":4,"instructions":"Brown chicken with onion and garlic. Add rice, tomato, stock, and spices. Cover and simmer until the rice is tender; fold through peas.","ingredients":[{"itemName":"chicken thighs","quantity":600,"unit":"g","notes":null},{"itemName":"rice","quantity":300,"unit":"g","notes":null},{"itemName":"chicken stock","quantity":750,"unit":"ml","notes":null},{"itemName":"diced tomatoes","quantity":1,"unit":"can","notes":null},{"itemName":"frozen peas","quantity":150,"unit":"g","notes":null}],"tags":["course-dinner","cuisine-caribbean","protein-chicken","method-one-pot"]},{"slug":"vegan-chili","title":"Vegan Bean Chili","description":"Tomato and bean chili suited to a weeknight dinner.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Chili%20(Vegan)","servings":4,"instructions":"Soften onion and capsicum. Add beans, tomatoes, corn, and chili seasoning. Simmer until thick, then serve with rice or tortillas.","ingredients":[{"itemName":"kidney beans","quantity":2,"unit":"can","notes":null},{"itemName":"diced tomatoes","quantity":2,"unit":"can","notes":null},{"itemName":"corn","quantity":1,"unit":"can","notes":null},{"itemName":"capsicum","quantity":1,"unit":"each","notes":null},{"itemName":"chili powder","quantity":2,"unit":"tsp","notes":null}],"tags":["course-dinner","cuisine-mexican","protein-legumes","dietary-vegan","method-one-pot"]},{"slug":"shepherds-pie","title":"Shepherd's Pie","description":"Baked lamb and vegetable pie under mashed potato.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Shepherd's%20Pie%20I","servings":4,"instructions":"Cook lamb with onion, carrot, peas, and gravy. Top with mashed potato and bake until browned and bubbling.","ingredients":[{"itemName":"lamb mince","quantity":500,"unit":"g","notes":null},{"itemName":"potatoes","quantity":800,"unit":"g","notes":null},{"itemName":"carrot","quantity":2,"unit":"each","notes":null},{"itemName":"frozen peas","quantity":150,"unit":"g","notes":null},{"itemName":"onion","quantity":1,"unit":"each","notes":null}],"tags":["course-dinner","cuisine-british","protein-lamb","method-oven"]},{"slug":"butter-chicken","title":"Indian Butter Chicken","description":"Mild tomato and butter chicken curry.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Indian%20Butter%20Chicken%20I","servings":4,"instructions":"Brown chicken with spices. Simmer with tomato puree, butter, and cream until tender. Serve with rice or naan.","ingredients":[{"itemName":"chicken breast","quantity":600,"unit":"g","notes":null},{"itemName":"tomato puree","quantity":1,"unit":"cup","notes":null},{"itemName":"cream","quantity":250,"unit":"ml","notes":null},{"itemName":"butter","quantity":40,"unit":"g","notes":null},{"itemName":"garam masala","quantity":2,"unit":"tsp","notes":null}],"tags":["course-dinner","cuisine-indian","protein-chicken","method-stovetop"]},{"slug":"chicken-tikka-masala","title":"Chicken Tikka Masala","description":"Spiced chicken in a tomato-yoghurt curry sauce.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Chicken%20Tikka%20Masala","servings":4,"instructions":"Coat chicken in yoghurt and spices, then brown. Simmer with onion, tomato, and cream until cooked through. Serve with rice.","ingredients":[{"itemName":"chicken thighs","quantity":600,"unit":"g","notes":null},{"itemName":"plain yoghurt","quantity":250,"unit":"ml","notes":null},{"itemName":"diced tomatoes","quantity":1,"unit":"can","notes":null},{"itemName":"cream","quantity":150,"unit":"ml","notes":null},{"itemName":"garam masala","quantity":2,"unit":"tsp","notes":null}],"tags":["course-dinner","cuisine-indian","protein-chicken","method-stovetop"]},{"slug":"chicken-andouille-gumbo","title":"Chicken and Andouille Gumbo","description":"Slow-simmered Louisiana stew with chicken and sausage.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Chicken%20and%20Andouille%20Sausage%20Gumbo","servings":4,"instructions":"Make a dark roux. Cook vegetables, then add chicken, sausage, stock, and seasoning. Simmer gently and serve over rice.","ingredients":[{"itemName":"chicken thighs","quantity":500,"unit":"g","notes":null},{"itemName":"smoked sausage","quantity":250,"unit":"g","notes":null},{"itemName":"chicken stock","quantity":1,"unit":"l","notes":null},{"itemName":"celery","quantity":3,"unit":"piece","notes":null},{"itemName":"capsicum","quantity":1,"unit":"each","notes":null}],"tags":["course-dinner","cuisine-cajun","protein-chicken","protein-pork","method-one-pot"]},{"slug":"gambas-al-ajillo","title":"Garlic Shrimp","description":"Spanish garlic shrimp with chilli and parsley.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Gambas%20al%20Ajillo%20(Garlic%20Shrimp)","servings":4,"instructions":"Warm olive oil with garlic and chilli. Add shrimp and cook just until pink. Finish with parsley and serve with bread or rice.","ingredients":[{"itemName":"raw shrimp","quantity":500,"unit":"g","notes":null},{"itemName":"garlic","quantity":5,"unit":"clove","notes":null},{"itemName":"olive oil","quantity":4,"unit":"tbsp","notes":null},{"itemName":"chili flakes","quantity":1,"unit":"tsp","notes":null},{"itemName":"parsley","quantity":1,"unit":"bunch","notes":null}],"tags":["course-dinner","cuisine-spanish","protein-seafood","method-stovetop","method-quick"]},{"slug":"rice-and-black-beans","title":"Rice and Black Beans","description":"Cuban-style beans and rice with citrus and herbs.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Rice%20with%20Black%20Beans%20(Arroz%20con%20Frijoles%20Negros)","servings":4,"instructions":"Cook onion, garlic, and spices. Add black beans and a little stock, simmer, then serve over rice with lime and coriander.","ingredients":[{"itemName":"black beans","quantity":2,"unit":"can","notes":null},{"itemName":"rice","quantity":300,"unit":"g","notes":null},{"itemName":"onion","quantity":1,"unit":"each","notes":null},{"itemName":"garlic","quantity":3,"unit":"clove","notes":null},{"itemName":"lime","quantity":1,"unit":"each","notes":null}],"tags":["course-dinner","cuisine-caribbean","protein-legumes","dietary-vegan","method-one-pot"]},{"slug":"coq-au-vin","title":"Coq au Vin","description":"French chicken braised with mushrooms and wine.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Coq%20au%20Vin%20I","servings":4,"instructions":"Brown chicken and bacon. Add onion, mushrooms, wine, and stock, then cover and braise until the chicken is tender.","ingredients":[{"itemName":"chicken thighs","quantity":800,"unit":"g","notes":null},{"itemName":"bacon","quantity":150,"unit":"g","notes":null},{"itemName":"mushrooms","quantity":250,"unit":"g","notes":null},{"itemName":"red wine","quantity":500,"unit":"ml","notes":null},{"itemName":"chicken stock","quantity":250,"unit":"ml","notes":null}],"tags":["course-dinner","cuisine-french","protein-chicken","protein-pork","method-one-pot"]},{"slug":"empanadas","title":"Beef Empanadas","description":"Baked pastry parcels with savory beef filling.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Empanada","servings":4,"instructions":"Cook beef with onion, spices, and tomato paste. Spoon into pastry circles, fold and seal, then bake until golden.","ingredients":[{"itemName":"beef mince","quantity":500,"unit":"g","notes":null},{"itemName":"shortcrust pastry","quantity":2,"unit":"packet","notes":null},{"itemName":"onion","quantity":1,"unit":"each","notes":null},{"itemName":"tomato paste","quantity":2,"unit":"tbsp","notes":null},{"itemName":"egg","quantity":1,"unit":"each","notes":null}],"tags":["course-dinner","cuisine-south-american","protein-beef","method-oven"]},{"slug":"spinach-ravioli","title":"Spinach Ravioli","description":"Filled pasta with ricotta, spinach, and tomato sauce.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Ravioli","servings":4,"instructions":"Mix ricotta and chopped spinach. Fill pasta sheets, seal, and boil until tender. Serve with warm tomato sauce.","ingredients":[{"itemName":"pasta sheets","quantity":400,"unit":"g","notes":null},{"itemName":"ricotta","quantity":250,"unit":"g","notes":null},{"itemName":"spinach","quantity":200,"unit":"g","notes":null},{"itemName":"tomato sauce","quantity":2,"unit":"cup","notes":null},{"itemName":"Parmesan","quantity":40,"unit":"g","notes":null}],"tags":["course-dinner","cuisine-italian","dietary-vegetarian","method-stovetop"]},{"slug":"spaghetti-puttanesca","title":"Spaghetti Puttanesca","description":"Bold tomato pasta with olives, capers, and anchovy.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Spaghetti%20alla%20Puttanesca","servings":4,"instructions":"Cook spaghetti. Simmer garlic, anchovy, tomatoes, olives, capers, and chilli. Toss with pasta and parsley.","ingredients":[{"itemName":"spaghetti","quantity":400,"unit":"g","notes":null},{"itemName":"diced tomatoes","quantity":1,"unit":"can","notes":null},{"itemName":"olives","quantity":150,"unit":"g","notes":null},{"itemName":"capers","quantity":2,"unit":"tbsp","notes":null},{"itemName":"anchovies","quantity":6,"unit":"piece","notes":null}],"tags":["course-dinner","cuisine-italian","protein-seafood","method-stovetop","method-quick"]},{"slug":"spaghetti-with-clams","title":"Spaghetti with Clams","description":"Garlicky Italian pasta with clams and herbs.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Spaghetti%20with%20Clams","servings":4,"instructions":"Cook spaghetti. Steam clams with garlic, wine, and tomato until opened. Toss with pasta and parsley, discarding unopened clams.","ingredients":[{"itemName":"spaghetti","quantity":400,"unit":"g","notes":null},{"itemName":"clams","quantity":1,"unit":"kg","notes":null},{"itemName":"garlic","quantity":4,"unit":"clove","notes":null},{"itemName":"white wine","quantity":250,"unit":"ml","notes":null},{"itemName":"parsley","quantity":1,"unit":"bunch","notes":null}],"tags":["course-dinner","cuisine-italian","protein-seafood","method-stovetop"]},{"slug":"ossobuco","title":"Ossobuco alla Milanese","description":"Italian braised veal shanks with tomato and citrus herb garnish.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Ossobuco%20Alla%20Milanese","servings":4,"instructions":"Brown veal shanks. Add vegetables, tomato, wine, and stock; cover and braise until tender. Finish with lemon-parsley gremolata.","ingredients":[{"itemName":"veal shanks","quantity":4,"unit":"piece","notes":null},{"itemName":"diced tomatoes","quantity":1,"unit":"can","notes":null},{"itemName":"white wine","quantity":250,"unit":"ml","notes":null},{"itemName":"beef stock","quantity":500,"unit":"ml","notes":null},{"itemName":"lemon","quantity":1,"unit":"each","notes":null}],"tags":["course-dinner","cuisine-italian","protein-beef","method-one-pot"]},{"slug":"mejadra","title":"Rice and Lentils (Mejadra)","description":"Fragrant lentils and rice topped with caramelised onions.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Rice%20and%20Lentils%20(Mejadra)","servings":4,"instructions":"Cook lentils until nearly tender. Fry onions slowly until dark and sweet. Simmer rice with lentils and spices, then top with onions.","ingredients":[{"itemName":"brown lentils","quantity":250,"unit":"g","notes":null},{"itemName":"rice","quantity":250,"unit":"g","notes":null},{"itemName":"onions","quantity":3,"unit":"each","notes":null},{"itemName":"cumin","quantity":1,"unit":"tsp","notes":null},{"itemName":"vegetable stock","quantity":750,"unit":"ml","notes":null}],"tags":["course-dinner","cuisine-middle-eastern","protein-legumes","dietary-vegan","method-one-pot"]},{"slug":"falafel-wraps","title":"Falafel Wraps","description":"Chickpea patties in warm flatbread with salad and tahini.","sourceUrl":"https://en.wikibooks.org/wiki/Cookbook:Falafel","servings":4,"instructions":"Blend chickpeas, onion, garlic, herbs, and spices. Shape into patties and bake or fry until crisp. Serve in pita with salad and tahini.","ingredients":[{"itemName":"chickpeas","quantity":2,"unit":"can","notes":null},{"itemName":"pita bread","quantity":4,"unit":"each","notes":null},{"itemName":"garlic","quantity":2,"unit":"clove","notes":null},{"itemName":"parsley","quantity":1,"unit":"bunch","notes":null},{"itemName":"tahini","quantity":4,"unit":"tbsp","notes":null}],"tags":["course-dinner","cuisine-mediterranean","protein-legumes","dietary-vegan","method-oven"]}]$recipes$::jsonb;
  v_tags jsonb := $tags$[{"slug":"course-dinner","label":"Dinner","category":"course"},{"slug":"cuisine-american","label":"American","category":"cuisine"},{"slug":"cuisine-asian","label":"Asian","category":"cuisine"},{"slug":"cuisine-british","label":"British","category":"cuisine"},{"slug":"cuisine-cajun","label":"Cajun","category":"cuisine"},{"slug":"cuisine-caribbean","label":"Caribbean","category":"cuisine"},{"slug":"cuisine-french","label":"French","category":"cuisine"},{"slug":"cuisine-indian","label":"Indian","category":"cuisine"},{"slug":"cuisine-italian","label":"Italian","category":"cuisine"},{"slug":"cuisine-mediterranean","label":"Mediterranean","category":"cuisine"},{"slug":"cuisine-mexican","label":"Mexican","category":"cuisine"},{"slug":"cuisine-middle-eastern","label":"Middle Eastern","category":"cuisine"},{"slug":"cuisine-south-american","label":"South American","category":"cuisine"},{"slug":"cuisine-spanish","label":"Spanish","category":"cuisine"},{"slug":"protein-beef","label":"Beef","category":"protein"},{"slug":"protein-chicken","label":"Chicken","category":"protein"},{"slug":"protein-lamb","label":"Lamb","category":"protein"},{"slug":"protein-legumes","label":"Legumes","category":"protein"},{"slug":"protein-pork","label":"Pork","category":"protein"},{"slug":"protein-seafood","label":"Seafood","category":"protein"},{"slug":"method-one-pot","label":"One pot","category":"method"},{"slug":"method-oven","label":"Oven","category":"method"},{"slug":"method-quick","label":"Quick","category":"method"},{"slug":"method-stovetop","label":"Stovetop","category":"method"},{"slug":"dietary-vegan","label":"Vegan","category":"dietary"},{"slug":"dietary-vegetarian","label":"Vegetarian","category":"dietary"}]$tags$::jsonb;
begin
  insert into public.curated_recipe_collections (
    slug, name, description, source_name, source_url, license_name, license_url, published
  ) values (
    'wikibooks-dinner-starter',
    'Wikibooks dinner starter collection',
    'Twenty-five adaptable dinner ideas sourced from Wikibooks Cookbook.',
    'Wikibooks Cookbook contributors',
    'https://en.wikibooks.org/wiki/Cookbook:Recipes',
    'CC BY-SA 4.0',
    'https://creativecommons.org/licenses/by-sa/4.0/',
    true
  )
  on conflict (slug) do update set
    name = excluded.name,
    description = excluded.description,
    source_name = excluded.source_name,
    source_url = excluded.source_url,
    license_name = excluded.license_name,
    license_url = excluded.license_url,
    published = excluded.published,
    updated_at = now()
  returning id into v_collection_id;

  insert into public.curated_tags (slug, label, category)
  select input.slug, input.label, input.category::public.curated_tag_category
  from jsonb_to_recordset(v_tags) as input(slug text, label text, category text)
  on conflict (slug) do update set label = excluded.label, category = excluded.category;

  insert into public.curated_recipes (
    collection_id, slug, title, description, source_url, servings, instructions, published
  )
  select
    v_collection_id,
    input.value->>'slug',
    input.value->>'title',
    input.value->>'description',
    input.value->>'sourceUrl',
    (input.value->>'servings')::numeric,
    input.value->>'instructions',
    true
  from jsonb_array_elements(v_recipes) input(value)
  on conflict (collection_id, slug) do update set
    title = excluded.title,
    description = excluded.description,
    source_url = excluded.source_url,
    servings = excluded.servings,
    instructions = excluded.instructions,
    published = excluded.published,
    updated_at = now();

  -- The globally curated source is refreshed atomically. Household adoption
  -- snapshots remain untouched because they live in public.recipes.
  delete from public.curated_recipe_tags rt
  using public.curated_recipes r
  where rt.curated_recipe_id = r.id and r.collection_id = v_collection_id;
  delete from public.curated_recipe_ingredients i
  using public.curated_recipes r
  where i.curated_recipe_id = r.id and r.collection_id = v_collection_id;

  insert into public.curated_recipe_ingredients (
    curated_recipe_id, item_name, quantity, unit, notes, display_order
  )
  select
    r.id,
    ingredient.value->>'itemName',
    (ingredient.value->>'quantity')::numeric,
    ingredient.value->>'unit',
    ingredient.value->>'notes',
    (ingredient.ordinality - 1)::integer
  from jsonb_array_elements(v_recipes) draft(value)
  join public.curated_recipes r
    on r.collection_id = v_collection_id and r.slug = draft.value->>'slug'
  cross join lateral jsonb_array_elements(draft.value->'ingredients') with ordinality ingredient(value, ordinality);

  insert into public.curated_recipe_tags (curated_recipe_id, curated_tag_id)
  select r.id, t.id
  from jsonb_array_elements(v_recipes) draft(value)
  join public.curated_recipes r
    on r.collection_id = v_collection_id and r.slug = draft.value->>'slug'
  cross join lateral jsonb_array_elements_text(draft.value->'tags') tag(slug)
  join public.curated_tags t on t.slug = tag.slug;
end;
$$;

-- Migration-time completeness assertion: the starter collection must remain
-- exactly 25 dinner recipes with five ordered ingredient lines each.
do $$
declare
  v_collection_id uuid;
begin
  select id into v_collection_id
  from public.curated_recipe_collections
  where slug = 'wikibooks-dinner-starter';
  if (select count(*) from public.curated_recipes where collection_id = v_collection_id) <> 25
    or exists (
      select 1
      from public.curated_recipes r
      where r.collection_id = v_collection_id
        and (select count(*) from public.curated_recipe_ingredients i where i.curated_recipe_id = r.id) <> 5
    ) then
    raise exception 'Wikibooks dinner starter collection is incomplete';
  end if;
end;
$$;
